onClick:
{{
  Update_Commande_Client.run()
    .then(() => Get_Commandes_Clients.run())
    .then((donnees) => {
      const idCommande = Table_commande_client.selectedRow.ID_Commande_Client;
      const commande = donnees ? donnees.find(c => String(c.ID_Commande_Client) === String(idCommande)) : null;

      const noteAttendue = inp_edit_notes.text || "";
      const clientAttendu = Select_client.selectedOptionValue;

      if (commande && String(commande.Notes || "") === String(noteAttendue) && String(commande.ID_Client) === String(clientAttendu)) {
        return true; 
      } else {
        return new Promise(resolve => setTimeout(resolve, 1500))
          .then(() => Get_Commandes_Clients.run());
      }
    })
    .then(() => {
      closeModal('modal_edit_commande');
      closeModal('Vue_detail_commande_client');

      // L'ASTUCE ICI : On force le tableau à recharger sa ligne sélectionnée avec les données fraîches
      return resetWidget('Table_commande_client', true);
    })
    .then(() => {
      showAlert('Commande modifiée avec succès !', 'success');

      setTimeout(() => {
        showModal('Vue_detail_commande_client');
      }, 500);
    })
    .catch((err) => {
      showAlert('Erreur : ' + (err.message || err), 'error');
    });
}}
